def investigate(context, acquire):
    events = context.get('events')
    if events is None:
        events = []
    count = 0
    status = 'open'
    pending = []
    for event in events:
        op = event.get('op')
        if op == 'feed':
            chunk = list(event.get('bytes'))
            data = pending + chunk
            pending = []
            index = 0
            total = len(data)
            while index < total:
                lead = data[index]
                if lead < 128:
                    count += 1
                    index += 1
                elif lead < 192:
                    status = 'error'
                    break
                elif lead < 224:
                    needed = 1
                    low = 128
                    high = 191
                elif lead < 240:
                    needed = 2
                    if lead < 225:
                        low = 160
                    else:
                        low = 128
                    if lead < 237:
                        high = 191
                    elif lead == 237:
                        high = 159
                    else:
                        low = 128
                        high = 191
                elif lead < 248:
                    needed = 3
                    if lead == 240:
                        low = 144
                    elif lead < 245:
                        low = 128
                    else:
                        low = 128
                    if lead < 244:
                        high = 191
                    elif lead == 244:
                        high = 143
                    else:
                        low = 128
                        high = 191
                else:
                    status = 'error'
                    break
                if index + needed >= total:
                    pending = data[index:]
                    index = total
                    break
                valid = True
                position = index + 1
                step = 0
                while step < needed:
                    byte = data[position]
                    if byte < low or byte > high:
                        valid = False
                    position += 1
                    step += 1
                    low = 128
                    high = 191
                if not valid:
                    status = 'error'
                    break
                count += 1
                index = position
            if status == 'error':
                pending = []
        elif op == 'finish':
            if len(pending) > 0:
                status = 'error'
                pending = []
            else:
                status = 'finished'
        elif op == 'reset':
            count = 0
            status = 'open'
            pending = []
    return {'count': count, 'status': status}
